mod records;
use hec_native_ic::{counted,instance::pick_instance,rng::Rng};
fn key<'a>(l:&'a str,k:&str)->Option<&'a str>{l.split_whitespace().find_map(|s|s.strip_prefix(&format!("{k}=")))}
fn old_vector(case:usize,modulus:u64)->[u64;16]{let line=include_str!("../native-lazy-finisher/CONTROL.txt").lines().find(|l|l.starts_with("COUNT g=3 p=61 ")&&key(l,"case")==Some(case.to_string().as_str())&&key(l,"arm")==Some("normalized")&&key(l,"rep")==Some("0")&&key(l,"modulus")==Some(modulus.to_string().as_str())).unwrap();let values=line.split("vector=[").nth(1).unwrap().trim_end_matches(']').split(',').map(|x|x.trim().parse().unwrap()).collect::<Vec<u64>>();values.try_into().unwrap()}
fn products(v:&[u64;16])->u64{v[4]+v[6]+v[11]}
fn cost(native:&counted::Counts)->[u64;4]{let p=native.get(&61).copied().unwrap_or([0;16]);let l=native.get(&124459).copied().unwrap_or([0;16]);[products(&p),p[9],products(&l),l[9]]}
fn gcd(mut a:u64,mut b:u64)->u64{while b!=0{let c=a%b;a=b;b=c;}a}
fn ratio_lower(a:&[u64;4],b:&[u64;4])->(u64,u64){let mut best=(a[0],b[0]);for i in 1..4{assert!(b[i]>0);if(a[i]as u128)*(best.1 as u128)<(best.0 as u128)*(b[i]as u128){best=(a[i],b[i]);}}let g=gcd(best.0,best.1);(best.0/g,best.1/g)}
fn main(){counted::disable();let inst=pick_instance(61,3).unwrap();assert_eq!(inst.c,5);assert_eq!(inst.ell,124459);let c=&inst.curve;let mut rng=Rng::new(2026111800^61^(3<<32));let mut baselines=Vec::new();for case in 0..2{let sm=if case==0{1}else{17};let d=c.mul(&inst.d1,sm);let label=1+rng.below(inst.ell-1);let target=c.mul(&d,label);let mut previous=None;for rep in 0..2{counted::reset();assert!(validate::eligible(c,&d,&target,inst.ell));let prep=prepared::prepare(c,false);let opts=pencil::Options{normalize:true,finish:false,seed:2026112200^61^(3<<32)^case as u64};let r=pencil::solve(c,&d,&target,inst.ell,512,false,&prep,opts);let core=counted::snapshot();counted::disable();assert_eq!(r.k,Some(label));for q in[61,124459]{assert_eq!(core[&q],old_vector(case,q),"frozen normalized core mismatch");}let old=include_str!("../native-lazy-finisher/CONTROL.txt").lines().find(|l|l.starts_with("OUTCOME g=3 p=61 ")&&key(l,"case")==Some(case.to_string().as_str())&&key(l,"arm")==Some("normalized")&&key(l,"rep")==Some("0")).unwrap();assert_eq!(old.split("report=").nth(1).unwrap(),format!("{r:?}"));counted::reset();assert_eq!(c.mul(&d,r.k.unwrap()),target);let verification=counted::snapshot();counted::disable();let mut total=core.clone();for(q,v)in &verification{let dst=total.entry(*q).or_insert([0;16]);for i in 0..16{dst[i]+=v[i];}}let result=(core.clone(),verification.clone(),total.clone(),format!("{r:?}"),prep.roots.sqrt_lookups.get(),prep.roots.legendre_lookups.get(),prep.roots.bytes());if let Some(ref p)=previous{assert_eq!(&result,p);}else{previous=Some(result);}println!("BASELINE case={case} sm={sm} rep={rep} k={label} original_h_verified=true core={core:?} independent_verification={verification:?} total={total:?} cost={:?}",cost(&total));if rep==0{baselines.push(cost(&total));}}}
for r in records::records(){let candidate=[r.pic[0]+r.pic[1]+r.pic[2]+products(&r.p),r.pic[3]+r.pic[4]+r.p[9],products(&r.ell),r.ell[9]];let cases=if let Some(k)=r.case{vec![k]}else{vec![0,1]};for case in cases{let b=baselines[case];let rho=ratio_lower(&candidate,&b);assert!((rho.0 as u128)*10>rho.1 as u128,"tenfold remains possible under this lower-bound screen");if r.case.is_none(){for i in 0..4{assert!((candidate[i]as u128)*16>=(b[i]as u128)*33,"setup 33/16 bound failed");}}println!("SCREEN map={} case={case} component={} candidate_lower_bound={candidate:?} normalized_total={b:?} any_nonnegative_price_ratio_at_least={}/{} tenfold_excluded_in_proxy=true",r.map,r.kind,rho.0,rho.1);}}
eprintln!("PASS normalized_replays=4 frozen_full_vectors_and_reports_exact=true independent_original_verification_charged=true setup_and_online_cost_model_screens=true no_walltime_or_isogeny_impossibility_claim=true");}
